CREATE TABLE truss.preparation_program_sources (program_id bigint PRIMARY KEY REFERENCES truss.preparation_program_registration (program_id), original_source_packet bytea NOT NULL CHECK (octet_length(original_source_packet) BETWEEN 1 AND 67108864), producer_identity bytea NOT NULL CHECK (octet_length(producer_identity) BETWEEN 1 AND 8192), issuer_xid xid8 NOT NULL CHECK (issuer_xid > '0'::xid8), issuer_actor_oid oid NOT NULL CHECK (issuer_actor_oid <> '0'::oid), issued_at timestamptz NOT NULL CHECK (isfinite(issued_at))); CREATE TRIGGER preparation_program_sources_immutable BEFORE DELETE OR UPDATE OR TRUNCATE ON truss.preparation_program_sources EXECUTE FUNCTION truss.catalog_immutable(); ALTER TABLE truss.preparation_program_sources ENABLE ALWAYS TRIGGER preparation_program_sources_immutable; REVOKE ALL ON truss.preparation_program_sources FROM public; REVOKE ALL ON TYPE truss.preparation_program_sources FROM public